// Guards the Tailwind coupling a module-remote build relies on: `returns`
// (and any future remote module) ships no CSS of its own — every `sq-*` /
// utility class it uses only renders correctly because the class also shows
// up in `dist/assets/*.css`, which Tailwind generated by scanning ALL of
// `pos/src` (see `tailwind.config.js`'s `content` glob), including the
// module's own source. That's true today only because the module's source
// still lives inside `pos/src` at build time — if it's ever published/built
// from outside this tree, a class used only in the module would silently
// not exist in the shipped CSS. This script makes that assumption checkable
// instead of a thing someone has to remember.
//
// Usage (after `npm run build`, so dist/assets/*.css exists):
//   node scripts/check-module-css-coverage.mjs src/modules/returns

import { readFileSync, readdirSync } from 'node:fs';
import path from 'node:path';

function walk(dir, matchExt) {
  const out = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walk(full, matchExt));
    else if (matchExt.some((ext) => entry.name.endsWith(ext))) out.push(full);
  }
  return out;
}

const moduleDir = process.argv[2];
if (!moduleDir) {
  console.error('usage: node scripts/check-module-css-coverage.mjs <module-dir>');
  process.exit(1);
}

const cssFiles = walk('dist/assets', ['.css']);
if (cssFiles.length === 0) {
  console.error('No dist/assets/*.css found — run `npm run build` first.');
  process.exit(1);
}
const css = cssFiles.map((f) => readFileSync(f, 'utf-8')).join('\n');

const sourceFiles = walk(moduleDir, ['.ts', '.tsx']);
const text = sourceFiles.map((f) => readFileSync(f, 'utf-8')).join('\n');

const PREFIXES = [
  'bg-', 'text-', 'border-', 'px-', 'py-', 'pt-', 'pb-', 'pl-', 'pr-', 'p-',
  'm-', 'mx-', 'my-', 'mt-', 'mb-', 'ml-', 'mr-', 'gap-', 'w-', 'h-', 'min-w',
  'min-h', 'max-w', 'max-h', 'rounded', 'shadow', 'space-', 'divide-',
  'overflow-', 'justify-', 'items-', 'shrink', 'grow', 'sq-', 'lg:', 'z-',
  'font-', 'select-', 'disabled:', 'hover:', 'focus:', 'opacity-', 'cursor-',
  'inset-', 'top-', 'bottom-', 'left-', 'right-',
];

const tokens = new Set(text.match(/[a-zA-Z][a-zA-Z0-9]*(?:-[a-zA-Z0-9[\].\/#%]+)+/g) ?? []);
const candidates = [...tokens].filter((t) => PREFIXES.some((p) => t.startsWith(p)));

const missing = candidates.filter((cls) => {
  const escaped = cls.replace(/([:.[\]/%#])/g, '\\$1');
  return !css.includes(escaped) && !css.includes(cls);
});

console.log(`Checked ${candidates.length} candidate classes from ${sourceFiles.length} files in ${moduleDir}`);

if (missing.length > 0) {
  console.error(`Missing from built CSS (${missing.length}):`);
  for (const m of missing) console.error(` - ${m}`);
  console.error(
    '\nThese classes are used in the module but never rendered by the host\'s ' +
      'Tailwind build. Either use them somewhere else in pos/src too, or add ' +
      'them to tailwind.config.js\'s `safelist`.',
  );
  process.exit(1);
}

console.log('OK — every class the module uses is present in the host CSS.');
